//-----------------------------------------------------------
// ThirdParty Events
//-----------------------------------------------------------

data class CreateThirdPartyEvent(
    @Id var thirdPartyId: UUID? = null,
    var name: String? = null,
    var taxId: String? = null,
         @AttributeOverrides(
      AttributeOverride( name = "street", column = Column(name = "address_street")),
      AttributeOverride( name = "city", column = Column(name = "address_city")),
      AttributeOverride( name = "state", column = Column(name = "address_state")),
      AttributeOverride( name = "postalCode", column = Column(name = "address_postalCode")),
      AttributeOverride( name = "country", column = Column(name = "address_country"))
    )
    var address: Address? = null,
    @Enumerated(EnumType.STRING) var partyType: ThirdPartyType? = null
)

data class UpdateThirdPartyEvent(
    @Id var thirdPartyId: UUID? = null,
    var name: String? = null,
    var taxId: String? = null,
         @AttributeOverrides(
      AttributeOverride( name = "street", column = Column(name = "address_street")),
      AttributeOverride( name = "city", column = Column(name = "address_city")),
      AttributeOverride( name = "state", column = Column(name = "address_state")),
      AttributeOverride( name = "postalCode", column = Column(name = "address_postalCode")),
      AttributeOverride( name = "country", column = Column(name = "address_country"))
    )
    var address: Address? = null,
    var subrogations:  Set<SubrogationRecovery>? = null,
    @Enumerated(EnumType.STRING) var partyType: ThirdPartyType? = null
)

data class DeleteThirdPartyEvent(@Id val thirdPartyId: UUID? = null)

